[Serializable] public class Invoice {
 public int Year; public int NrCrt; public string Transportator=""; public string Comanda=""; public string Factura=""; public decimal TotalLei; public decimal TotalEur; public string Iban=""; public DateTime DataPrimire=DateTime.Today; public int ZileScadenta=30; public DateTime Scadenta=DateTime.Today.AddDays(30); public string ScadentaText=""; public bool ScadentaInvalida=false; public DateTime? DataPlatii; public string Observatii="";
 public bool Platita { get { return DataPlatii.HasValue; } }
}
