  var company=new Label{Text="OCTAV TRANSPORT LOGISTIC",ForeColor=Color.FromArgb(190,210,225),Font=new Font("Segoe UI",9F,FontStyle.Bold),AutoSize=true,Left=28,Top=67}; header.Controls.Add(company);
